std::string markdown_to_html(const std::string& markdown) {
    std::string html;
    std::stringstream ss(markdown);
    std::string line;
    while (std::getline(ss, line)) {
        // Replace markdown formatting with html tags
        line = std::regex_replace(line, std::regex("\\*(.*?)\\*"), "<strong>$1</strong>");
        line = std::regex_replace(line, std::regex("\\/(.*?)\\/"), "<em>$1</em>");
        line = std::regex_replace(line, std::regex("\\[(.*?)\\](.*?)\\[\\/(.*?)\\]"), "<a href=\"$2\">$1</a>");
        html += line + "\n";
    }
    return html;
}

int main() {
    std::string markdown = "This is *bold* text. This is /italic/ text. [This is a link](https://example.com).";
    std::string html = markdown_to_html(markdown);
    std::cout << html << std::endl;
    return 0;
}
```

